'use strict';
// City photo maps, added one by one. Keyed 'A3:City Name' so the lookup
// survives city-id ordering. Embedded as data URIs because the GitHub
// push tool only handles UTF-8 text files, so binary images cannot be
// pushed that way. A city with an entry here opens its photo map instead
// of the generated isometric view, with no store or company pins on it.
const CITY_MAPS = {
  'USA:San Francisco': 'data:image/jpeg;base64,',
};

function cityMapFor(city) {
  if (!city) return null;
  return CITY_MAPS[city.a3 + ':' + city.name] || null;
}
